/** 
 * Converts logical type value to a proto using a default type coder. 
 */
private static LogicalTypeValue logicalTypeToProto(FieldType baseType, FieldType inputType, Object value) {
  try {
    PipedInputStream in = new PipedInputStream();
    PipedOutputStream out = new PipedOutputStream(in);
    SchemaCoderHelpers.coderForFieldType(inputType).encode(value, out);
    out.close();
    Object baseObject;
    switch (baseType.getTypeName()) {
      case INT64:
        baseObject = new DataInputStream(in).readLong();
        break;
      case BYTES:
        baseObject = ByteStreams.toByteArray(in);
        break;
      default:
        throw new UnsupportedOperationException("Unsupported underlying type for producing LogicalType via coder.");
    }
    try {
      return LogicalTypeValue.newBuilder().setValue(fieldValueToProto(baseType, baseObject)).build();
    } catch (IllegalStateException e) {
      throw new RuntimeException("Failed to process fieldValueToProto due to invalid map entry state", e);
    }
  } catch (IOException e) {
    throw new RuntimeException(e);
  }
}
